import{_ as p,a0 as l,w as o,s as r,ao as d,I as i,x as s,a1 as n,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const $=JSON.parse('{"title":"awk 系列：如何使用 awk 比较操作符 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 比较操作符 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 比较操作符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 比较操作符 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 4 - How to Use Comparison Operators with Awk in Linux","title":"awk 系列：如何使用 awk 比较操作符","tag":"awk","desc":""},"relativePath":"awk/Part 4 - How to Use Comparison Operators with Awk in Linux.md","filePath":"[post].md"}'),k={name:"awk/Part 4 - How to Use Comparison Operators with Awk in Linux.md"};function c(w,a,u,h,g,m){const t=l("Link");return o(),r("div",null,[a[13]||(a[13]=d(`<h1 id="awk-系列-如何使用-awk-比较操作符" tabindex="-1">awk 系列：如何使用 awk 比较操作符 <a class="header-anchor" href="#awk-系列-如何使用-awk-比较操作符" aria-label="Permalink to “awk 系列：如何使用 awk 比较操作符”">​</a></h1><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Use-Comparison-Operators-with-AWK.png" alt=""></p><p>对于 使用 awk 命令的用户来说，处理一行文本中的数字或者字符串时，使用比较运算符来过滤文本和字符串是十分方便的。</p><p>在 awk 系列的此部分中，我们将探讨一下如何使用比较运算符来过滤文本或者字符串。如果你是程序员，那么你应该已经熟悉了比较运算符；对于其它人，下面的部分将介绍比较运算符。</p><h3 id="awk-中的比较运算符是什么" tabindex="-1">awk 中的比较运算符是什么？ <a class="header-anchor" href="#awk-中的比较运算符是什么" aria-label="Permalink to “awk 中的比较运算符是什么？”">​</a></h3><p>awk 中的比较运算符用于比较字符串和或者数值，包括以下类型：</p><ul><li><code>&gt;</code> – 大于</li><li><code>&lt;</code> – 小于</li><li><code>&gt;=</code> – 大于等于</li><li><code>&lt;=</code> – 小于等于</li><li><code>==</code> – 等于</li><li><code>!=</code> – 不等于</li><li><code>some_value ~ / pattern/</code> – 如果 some_value 匹配模式 pattern，则返回 true</li><li><code>some_value !~ / pattern/</code> – 如果 some_value 不匹配模式 pattern，则返回 true</li></ul><p>现在我们通过例子来熟悉 awk 中各种不同的比较运算符。</p><p>在这个例子中，我们有一个文件名为 food_list.txt 的文件，里面包括不同食物的购买列表。我想给食物数量小于或等于 30 的物品所在行的后面加上<code>(**)</code></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>File – food_list.txt</span></span>
<span class="line"><span>No      Item_Name               Quantity        Price</span></span>
<span class="line"><span>1       Mangoes                    45           $3.45</span></span>
<span class="line"><span>2       Apples                     25           $2.45</span></span>
<span class="line"><span>3       Pineapples                 5            $4.45</span></span>
<span class="line"><span>4       Tomatoes                   25           $3.45</span></span>
<span class="line"><span>5       Onions                     15           $1.45</span></span>
<span class="line"><span>6       Bananas                    30           $3.45</span></span></code></pre></div><p>Awk 中使用比较运算符的通用语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 表达式 { 动作; }</span></span></code></pre></div><p>为了实现刚才的目的，执行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;$3 &lt;= 30 { printf &quot;%s\\t%s\\n&quot;, $0,&quot;**&quot; ; } $3 &gt; 30 { print $0 ;}&#39; food_list.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No	Item_Name\`		Quantity	Price</span></span>
<span class="line"><span>1	Mangoes	      		   45		$3.45</span></span>
<span class="line"><span>2	Apples			   25		$2.45	**</span></span>
<span class="line"><span>3	Pineapples		   5		$4.45	**</span></span>
<span class="line"><span>4	Tomatoes		   25		$3.45	**</span></span>
<span class="line"><span>5	Onions			   15           $1.45	**</span></span>
<span class="line"><span>6	Bananas			   30           $3.45	**</span></span></code></pre></div><p>在刚才的例子中，发生如下两件重要的事情：</p><ul><li>第一个“表达式 {动作;}”组合中， <code>$3 &lt;= 30 { printf “%s\\t%s\\n”, $0,”**” ; }</code> 打印出数量小于等于30的行，并且在后面增加<code>(**)</code>。物品的数量是通过 <code>$3</code> 这个域变量获得的。</li><li>第二个“表达式 {动作;}”组合中， <code>$3 &gt; 30 { print $0 ;}</code> 原样输出数量小于等于 <code>30</code> 的行。</li></ul><p>再举一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;$3 &lt;= 20 { printf &quot;%s\\t%s\\n&quot;, $0,&quot;TRUE&quot; ; } $3 &gt; 20  { print $0 ;} &#39; food_list.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>No	  Item_Name		Quantity	Price</span></span>
<span class="line"><span>1	    Mangoes			   45		  $3.45</span></span>
<span class="line"><span>2	    Apples			   25		  $2.45</span></span>
<span class="line"><span>3	    Pineapples		  5		  $4.45	TRUE</span></span>
<span class="line"><span>4	    Tomatoes		   25		  $3.45</span></span>
<span class="line"><span>5	    Onions			   15     $1.45	TRUE</span></span>
<span class="line"><span>6     Bananas	       30     $3.45</span></span></code></pre></div><p>在这个例子中，我们想通过在行的末尾增加 (TRUE) 来标记数量小于等于20的行。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>这是一篇对 awk 中的比较运算符介绍性的指引，因此你需要尝试其他选项，发现更多使用方法。</p><p>如果你遇到或者想到任何问题，请在下面评论区留下评论。请记得阅读 awk 系列下一部分的文章，那里我将介绍组合表达式。</p><hr>`,23)),i("p",null,[a[1]||(a[1]=s("via: ",-1)),n(t,{href:"http://www.tecmint.com/comparison-operators-in-awk/"},{default:e(()=>[...a[0]||(a[0]=[s("http://www.tecmint.com/comparison-operators-in-awk/",-1)])]),_:1})]),i("p",null,[a[5]||(a[5]=s("作者：",-1)),n(t,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...a[2]||(a[2]=[s("Aaron Kili",-1)])]),_:1}),a[6]||(a[6]=s(" 译者：",-1)),n(t,{href:"https://github.com/chunyang-wen"},{default:e(()=>[...a[3]||(a[3]=[s("chunyang-wen",-1)])]),_:1}),a[7]||(a[7]=s(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:e(()=>[...a[4]||(a[4]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[10]||(a[10]=s("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[8]||(a[8]=[s("LCTT",-1)])]),_:1}),a[11]||(a[11]=s(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:e(()=>[...a[9]||(a[9]=[s("Linux中国",-1)])]),_:1}),a[12]||(a[12]=s(" 荣誉推出",-1))])])}const T=p(k,[["render",c]]);export{$ as __pageData,T as default};
